insert into public.training_drills(team_id,is_template,title,category,difficulty,role_tags,duration_minutes,objective,setup,steps,success_criteria,scoring_rubric,tags)
values
(null,true,'2v2 Entry + Trade Window','entry-trade','medium',array['P1 Primary Rusher','P2 Secondary Rusher'],20,'P1 takes first contact while P2 is close enough to trade immediately.','Pair up; define entry and trade roles; repeat controlled engagements.',array['P1 calls entry and target','P2 confirms distance and angle','P1 commits only after confirmation','P2 trades within the agreed window','Both regroup and report outcome'],'P2 can trade without hesitation; both players survive or reset together.', '{"trade_timing":40,"spacing":25,"callouts":20,"reset":15}'::jsonb,array['rusher','teamwork','trade']),
(null,true,'IGL 5-Second Call Drill','communication','advanced',array['P4 Sniper + IGL','All players'],15,'Deliver one actionable call in five seconds: information, decision, acknowledgement.','Coach reads a scenario; team answers with the comms protocol.',array['State zone/enemy information','Give one clear action','Each player acknowledges','IGL checks execution','Update after new information'],'Call is concise, unambiguous and acknowledged by all.', '{"clarity":30,"timeliness":25,"acknowledgement":25,"update":20}'::jsonb,array['igl','communication']),
(null,true,'Early Rotation Trigger','rotation','medium',array['P4 Sniper + IGL','All players'],25,'Recognize when to rotate before zone pressure or third-party risk.','Use custom-room/map scenarios; identify route and checkpoints.',array['Read zone and nearby teams','Choose rotate timing','Assign scout/cover roles','Move as a unit','Confirm safe position and next trigger'],'Rotation begins on the agreed trigger with no unplanned split.', '{"timing":35,"route":25,"coordination":25,"safety":15}'::jsonb,array['rotation','macro']),
(null,true,'Flank Timing + Information','flank','advanced',array['P3 Third Rusher / Flanker'],20,'Create pressure from a safe angle without losing team trade distance.','P3 practices route, timing and information-only abort conditions.',array['Confirm main team pressure','Choose cover-safe flank','Report position and ETA','Pressure only on IGL cue','Regroup on abort call'],'Flank produces useful information/pressure and returns on cue.', '{"timing":30,"info":30,"cover":20,"regroup":20}'::jsonb,array['flank','positioning']),
(null,true,'Backup Distance & Crossfire','backup','medium',array['P2 Secondary Rusher','P3 Third Rusher / Flanker'],20,'Maintain support distance and avoid isolated angles.','Team marks primary angle and backup angle in custom room.',array['P1 identifies first angle','P2 sets trade angle','P3 covers escape/third angle','Call gaps before contact','Reset together'],'No player enters an engagement without a trade/cover plan.', '{"spacing":35,"angle":25,"calls":20,"reset":20}'::jsonb,array['backup','crossfire']),
(null,true,'Controlled Retreat + Regroup','squad-coordination','medium',array['All players'],15,'Disengage cleanly and regroup without one player being left behind.','Practice retreat calls under simulated pressure.',array['IGL gives retreat call','Players acknowledge','Smoke/cover roles if available','Move to rally point','Count roster and reset'],'All active players reach rally point and confirm status.', '{"call":25,"cover":25,"movement":25,"roster_check":25}'::jsonb,array['regroup','discipline']),
(null,true,'End-Zone Position Priority','endgame','advanced',array['P4 Sniper + IGL','All players'],25,'Prioritize playable cover, information and team spacing in final zone.','Use end-zone map scenario and discuss three options.',array['Identify safe playable cover','Compare rotation risk','Assign hold/scan/cover roles','Define fight trigger','Define retreat/reposition trigger'],'Team states position, trigger, roles and fallback clearly.', '{"position":30,"decision":30,"role":20,"fallback":20}'::jsonb,array['endgame','igl']),
(null,true,'Primary Rusher Entry Discipline','role','medium',array['P1 Primary Rusher'],20,'Take controlled first contact with information and exit plan.','P1 repeats entry scenarios with coach feedback.',array['Gather info before entry','Call target and direction','Commit on backup confirmation','Avoid chasing without team','Reset or finish on IGL call'],'Entry is purposeful and backup-aware, not solo chase.', '{"info":25,"timing":30,"backup":25,"discipline":20}'::jsonb,array['p1','entry']),
(null,true,'Sniper Info → IGL Decision','igl','advanced',array['P4 Sniper + IGL'],20,'Turn long-range observations into a useful team decision.','P4 receives simulated sighting/zone changes.',array['Call exact direction/distance','Separate confirmed from uncertain info','Recommend one action','Get acknowledgement','Update when info changes'],'Team receives precise, decision-ready info without clutter.', '{"accuracy":35,"brevity":25,"decision":25,"update":15}'::jsonb,array['p4','sniper']),
(null,true,'Post-Match One-Fix Review','communication','beginner',array['All players'],15,'Convert one repeated mistake into a concrete next-session action.','Review one match/event; avoid blame and kill-only conclusions.',array['Name the observable mistake','Find root cause','State impact','Define correct action','Assign owner and next drill'],'One measurable improvement action is assigned and understood.', '{"evidence":25,"root_cause":25,"action":30,"ownership":20}'::jsonb,array['review','improvement'])
